WITH cleaned AS (SELECT id, supplier_name, country, city, TRIM(supplier_name) AS clean_supplier_name, UPPER(supplier_name) AS supplier_name_upper FROM suppliers WHERE country = 'UK') SELECT s.id, s.supplier_name, s.country, s.city, s.clean_supplier_name, s.supplier_name_upper, x.product_category FROM cleaned s LEFT JOIN LATERAL (SELECT c.category AS product_category FROM products c WHERE c.supplier_id = s.id ORDER BY c.cost DESC, c.id DESC LIMIT 1) x ON TRUE;
